  "id": 4,
  "knowledge": "Net Worth",
  "description": "Calculates the financial value of a customer by subtracting liabilities from assets.",
  "definition": "Net Worth = \\text{Total Assets} - \\text{Total Liabilities} = totassets - totliabs = networth"
}

args.sql:
ALTER TABLE employment_and_income
ADD COLUMN financial_stability_index DECIMAL(5, 3);

UPDATE employment_and_income AS e
SET financial_stability_index = 0.5 * debincratio + 0.5 * (1 - (SELECT liqassets FROM expenses_and_assets AS ex WHERE ex.expemplref = e.emplcoreref)/NULLIF(mthincome * 6, 0));

